g=[[0]*22 for _ in range(22)]
def put(r,c,v):
    assert 0<=r<22 and 0<=c<22
    assert g[r][c] in (0,v), (r,c,g[r][c],v)
    g[r][c]=v
# 7 piece moved +1 col
for r,cs in [(3,range(3,7)),(4,[3]),(5,[3]),(6,range(3,7))]:
    for c in cs: put(r,c,7)
# 8 piece moved +14 rows, -7 cols
for r,cs in [(16,[9,13]),(17,range(9,14))]:
    for c in cs: put(r,c,8)
# central 4
for r in range(8,11):
    for c in range(10,13): put(r,c,4)
# 3 piece moved -11 rows, -6 cols
for r,cs in [(2,range(8,14)),(3,[8,13]),(4,[8,13]),(5,[8,13]),(6,[8]),(7,range(8,11))]:
    for c in cs: put(r,c,3)
# 9 piece moved -6 rows, +7 cols
for r,cs in [(12,[10,12]),(13,[10,12]),(14,range(9,14))]:
    for c in cs: put(r,c,9)
# markers, with paired shared ports
markers=[(3,7),(6,7),(1+14,16-7),(1+14,20-7), # 8 top connectors
         (7,11),(9,9),(11,10),(11,12),
         (3,7),(5,13),(6,7),(7,11),
         (11,10),(11,12),(15,9),(15,13)]
for r,c in markers: put(r,c,2)
print('\n'.join(' '.join(map(str,row)) for row in g))

